 assert [r['index'] for r in report['assessments']]==IDS and len(report['proposed_ledger_relationships'])==13
 counts={'queue_records':3713,'partial_before':1379,'unassessed_before':2334,'partial_after':1400,'unassessed_after':2313,'ledger_before':1115,'proposed_relationships':13,'ledger_after':1128,'queue_closures':0,'lens_completions':0,'accepted_unique_defect_increment':0};assert report['counts_if_adopted']==counts
 by_label={r['label']:r for r in source_map['reports']};assert len(by_label)==len(source_map['reports'])==17
 baseline,progress,queue=(json.loads(before[n]) for n in NAMES[:3]);doc=before[NAMES[3]].decode();oldb=copy.deepcopy(baseline);oldp=copy.deepcopy(progress);oldq=copy.deepcopy(queue)
 assert baseline['source_revision']==progress['source_revision']==REV;entries=queue['entries'];ledger=baseline['newly_assessed_ledger']['entries'];assert len(entries)==3713 and len(ledger)==1115
