 history={'original_queue_sha256':'2e1f4430edb375adff24b6b46d434ac58bf5fd18c0d9dda4cf92fe215e5cfe08','reconstructed_queue_sha256':'3695264e6d4531a1137f0c3232e0d5163d941c49849cb4bddef31cd8403fd173','selected_queue_objects_equal_as_parsed':True,'whole_stream_bytes_equal':False,'qualification':'Selected original and reconstructed 059 objects match as parsed; full streams differ, and neither is the missing checkpoint3821.'}
 for rel in relations:
  assert all(0<=i<len(entries) for i in rel['queue']) and all(0<=i<1115 for i in rel['ledger'])
  ledger.append({'id':rel['id'],'assessed_lenses':sorted({assessed[i] for i in rel['queue'] if i in assessed}),'classification':rel['classification'],'historical_related_records':['baseline-059/queue.json#/entries/'+str(i) for i in rel['queue']],'current_related_records':['BASELINE-95E-20261110.json#/newly_assessed_ledger/entries/'+str(i) for i in rel['ledger']],'relationship_qualification':rel['qualification'],'connected_repair_direction':rel['direction'],'discovery':'partial; supported reach, policy, source complements and exact aliases remain open','repair':'not started','validation':'not performed','record':REPORT,'historical_original_and_reconstruction':copy.deepcopy(history)})
 for a in report['assessments']:
  i=a['index'];row=entries[i];assert (row['contract_id'],row['historical_lens'],row['historical_status'],row['current_reconciliation'])==(a['contract'],a['lens'],a['historical_status_projection'],'unassessed');assert 'further_current_evidence' not in row and all(x in by_label for x in a['source_report_labels'])
  archives=list(dict.fromkeys(by_label[x]['archive'] for x in a['source_report_labels']));row['current_reconciliation']='partial current 95e source assessment and historical relationship; see '+REPORT+'; no semantic queue or lens closure and no checkpoint3821 attribution';row['further_current_evidence']=[REPORT,'delegated/post76fe-followups/reconciliation/SOURCE-MAP.json',*archives]
 assert sum(x['current_reconciliation'].startswith('partial') for x in entries)==1400 and sum(x['current_reconciliation']=='unassessed' for x in entries)==2313 and len(ledger)==1128
 assert progress['new_current_ledger_candidates']==1115 and progress['lenses_complete']==progress['queue_records_semantically_reconciled']==0 and baseline['historical_queue_records_semantically_reconciled']==0 and progress['repair']=='not started' and progress['product_validation']=='not performed'
 progress['new_current_ledger_candidates']=1128;progress['central_post76fe_bounded_reconciliations']=REPORT+'; 21 partial assessments and 13 planning relationships, with no semantic closure or accepted unique-defect increment.';progress['post76fe_queue_snapshot']='3,713 indexed: 1,400 partial and 2,313 unassessed; all remain semantically unreconciled.';progress['post76fe_prior_pending_qualification']='Earlier pending snapshots retain their original counts; q3344, q3353, q3354, q3356, q3368 and q3462 now have partial current assessments.';progress['post76fe_same_machine_recovery']='delegated/post76fe-followups/minimal-recovery/RECOVERY-SUMMARY.json; first successor guard failed, then two separately qualified alternate-dependent replays passed.';progress['main_recheck_20261113_1012']=MAIN;progress['current_main_qualification']='GitHub connector observed main at 95e between '+observation['before_utc']+' and '+observation['after_utc']+'; this is point-in-time and main may advance. See '+MAIN+'.';baseline['latest_main_recheck']=MAIN
 marker='product validation is authorized here.\n\n';assert doc.count(marker)==1
 paras=[REPORT+' records 21 bounded partial assessments and 13 planning relationships. The working queue has 1,400 partial and 2,313 unassessed records, all semantically unreconciled; the ledger has 1,128 entries and relationships, not unique defects. No queue record or lens is closed and no unique-defect increment is accepted.','delegated/post76fe-followups/INDEX.md locates the separately attributed source packets, custody evidence, failed and successful recovery replays, and minimal Git-object dependencies. The original 059 and reconstructed selected records agree as parsed while their full streams differ. Missing checkpoint 3821, SOURCE004 and the 73 nontext/no-positive-EOF contracts remain open.','MAIN-RECHECK-20261113-1012.json records a point-in-time main observation; main may advance. The earlier paragraphs below retain their historical snapshot counts.']
 text='\n\n'.join(textwrap.fill('`'+s.split(' ',1)[0]+'` '+s.split(' ',1)[1],width=80,break_long_words=False,break_on_hyphens=False) for s in paras)+'\n\n';doc=doc.replace(marker,marker+text,1)
 assert queue.keys()==oldq.keys() and all(queue[k]==oldq[k] for k in queue if k!='entries')
 for i,(old,new) in enumerate(zip(oldq['entries'],entries)):
  if i not in IDS:assert old==new
  else:assert {k:v for k,v in new.items() if k not in ('current_reconciliation','further_current_evidence')}=={k:v for k,v in old.items() if k!='current_reconciliation'}
 assert ledger[:1115]==oldb['newly_assessed_ledger']['entries'] and all(baseline[k]==oldb[k] for k in oldb if k not in ('newly_assessed_ledger','latest_main_recheck')) and baseline['newly_assessed_ledger']['qualification']==oldb['newly_assessed_ledger']['qualification']
 assert all(progress[k]==oldp[k] for k in oldp if k not in ('new_current_ledger_candidates','current_main_qualification'))
 return {NAMES[0]:render(baseline),NAMES[1]:render(progress),NAMES[2]:render(queue),NAMES[3]:doc.encode()}
